sealed class AttemptWorker(
    IAttemptStore store,
    IBus bus,
    TokenParser parser)
{
    public async Task HandleAsync(string messageId, string body, CancellationToken ct)
    {
        var token = parser.Parse(body);
        await store.SaveAsync(token.AttemptId, ct);
        await bus.PublishAsync(token.AttemptId, ct);
    }
}

abstract class TokenParser
{
    public AuthToken Parse(string raw) => ParseCore(raw);
    protected abstract AuthToken ParseCore(string raw);
}
